script:
test("six payments within nine minutes raise an alert at 10:09", function () {
  var result = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:09:00Z"
    ]
  });
  assert.deepEqual(result, { alert: true, alertTime: "2024-01-01T10:09:00Z" });
});

test("a payment exactly ten minutes after the first is in a different period and does not alert", function () {
  var result = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:10:00Z"
    ]
  });
  assert.deepEqual(result, { alert: false, alertTime: null });
});

test("five payments within eight minutes do not raise an alert", function () {
  var result = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z"
    ]
  });
  assert.deepEqual(result, { alert: false, alertTime: null });
});

test("six payments each exactly ten minutes apart do not raise an alert", function () {
  var result = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:10:00Z",
      "2024-01-01T10:20:00Z",
      "2024-01-01T10:30:00Z",
      "2024-01-01T10:40:00Z",
      "2024-01-01T10:50:00Z"
    ]
  });
  assert.deepEqual(result, { alert: false, alertTime: null });
});

test("a sixth payment in a later period raises an alert at 10:16", function () {
  var result = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:01:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:03:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:11:00Z",
      "2024-01-01T10:12:00Z",
      "2024-01-01T10:13:00Z",
      "2024-01-01T10:14:00Z",
      "2024-01-01T10:15:00Z",
      "2024-01-01T10:16:00Z"
    ]
  });
  assert.deepEqual(result, { alert: true, alertTime: "2024-01-01T10:16:00Z" });
});

test("six payments from 10:05 through 10:10 raise an alert at 10:10", function () {
  var result = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:05:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:07:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:09:00Z",
      "2024-01-01T10:10:00Z"
    ]
  });
  assert.deepEqual(result, { alert: true, alertTime: "2024-01-01T10:10:00Z" });
});

test("a later payment does not replace the alert time", function () {
  var result = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:09:00Z",
      "2024-01-01T10:30:00Z"
    ]
  });
  assert.deepEqual(result, { alert: true, alertTime: "2024-01-01T10:09:00Z" });
});

test("one payment does not raise an alert", function () {
  var result = code.checkCardPayments({
    paymentTimes: ["2024-01-01T10:00:00Z"]
  });
  assert.deepEqual(result, { alert: false, alertTime: null });
});
